from multiprocessing import Pool

t='((..(((..((((..((....((..((((....))....))..))))..))....))..))((..((..((..((((..((....((..((((..((....((....))))..))....))..))))..))((..((..((....))((..((((..((....((..((((....))....))..))))..))....))..))))..))..))..))((..((....((..((((..((....((....))))..))....))..))))..))))..))..)..))'
n=len(t)
stack=[];pairmap=[-1]*n
for i,c in enumerate(t):
    if c=='(':
        stack.append(i)
    elif c==')':
        j=stack.pop();pairmap[i]=j;pairmap[j]=i
hairpins=[]
for i in range(n):
    if pairmap[i]>i:
        j=pairmap[i]
        inner=[k for k in range(i+1,j)]
        if all(pairmap[k]==-1 for k in inner) and len(inner)==4:
            hairpins.append((i,j,inner))

def build_seed(rng):
    seq=['A']*n
    for (i,j,inner) in hairpins:
        for k,pos in enumerate(inner): seq[pos]='GAAA'[k]
        seq[i]='C';seq[j]='G'
    comp={'G':'C','C':'G','A':'U','U':'A'}
    pairtypes=[('G','C'),('C','G'),('A','U'),('U','A')]
    for i in range(n):
        if pairmap[i]>i:
            j=pairmap[i]
            if seq[i]=='A':
                pt=rng.choice(pairtypes)
                seq[i]=pt[0];seq[j]=pt[1]
    return ''.join(seq)

def score(s):
    fc=RNA.fold_compound(s)
    ss,mfe=fc.mfe()
    return RNA.bp_distance(ss,t), ss

def sa_run(args):
    seed_id, iters = args
    rng=random.Random(seed_id*1000+1)
    cur=list(build_seed(rng))
    bd,ss=score(''.join(cur))
    cur_bd=bd
    comp={'G':'C','C':'G','A':'U','U':'A'}
    best_seq=list(cur); best_bd=cur_bd
    for it in range(iters):
        if cur_bd==0:
            return ''.join(cur),0
        T=max(0.05, 2.0*(1-it/iters))
        i=rng.randint(0,n-1)
        old=cur[i]
        choices=[c for c in 'ACGU' if c!=old]
        new=rng.choice(choices)
        j=pairmap[i]
        saved=[cur[i]]
        cur[i]=new
