            cur_bd=bd
            if bd<best_bd:
                best_bd=bd; best_seq=list(cur)
        else:
            cur[i]=saved[0]
            if j>=0: cur[j]=saved[1]
    return ''.join(best_seq),best_bd

if __name__=='__main__':
